 function downloadContacts(){const cols=["firstName","lastName","phone","email","companyName","status","notes"];const csv=[cols.join(","),...contacts.map(c=>cols.map(k=>'"'+String((c as any)[k]||"").replace(/"/g,'""')+'"').join(","))].join("\r\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download="realdesk-contacts.csv";a.click();URL.revokeObjectURL(a.href)}
